PROGRAM EulerProblem609(OUTPUT);

{ pi(m) is the number of primes not exceeding m. A pi-sequence is a chain
  u_0, u_1 = pi(u_0), u_2 = pi(u_1), ... with every term >= 1 and at least
  two terms. c(u) counts the non-prime terms of u. p(n,k) is the number of
  pi-sequences with u_0 <= n and c(u) = k; P(n) is the product of the
  nonzero p(n,k).

  Direct simulation of every chain from every u_0 up to n is far too slow
  for n = 10^8, so this exploits two facts instead:

  - All u_0 with the same v = pi(u_0) share the same tail chain
    v, pi(v), pi(pi(v)), ... Since consecutive primes prime(v), prime(v+1)
    bracket exactly the u_0 with pi(u_0) = v, and that interval
    [prime(v), prime(v+1)-1] contains exactly one prime (prime(v) itself),
    we only need to walk the tail chain once per v (v ranges only up to
    pi(n), not n) and weight each step by 1 (for the prime u_0 = prime(v))
    or by the non-prime count of the rest of the interval.
  - pi is strictly decreasing along a chain once past u_0, so a single
    sieve up to n also gives pi(m) for every m <= pi(n) via a prefix sum,
    with no second sieve needed. }

TYPE
  BYTEBUF = SUPER ARRAY [0..*] OF WORD8;
  PBYTEBUF = ^BYTEBUF;
  INTBUF = SUPER ARRAY [0..*] OF INTEGER32;
  PINTBUF = ^INTBUF;

CONST
  MAXK = 63;

VAR
  n, i, j, m, idx, k, v: INTEGER32;
  isComposite: PBYTEBUF;
  primes: PINTBUF;
  piOf: PINTBUF;
  cur, cval: INTEGER32;
  primeVal, nextPrimeVal, intervalEnd, numNonPrime: INTEGER32;
  p: ARRAY [0..MAXK] OF INTEGER64;
  modulus, answer: INTEGER64;
  chainDone: BOOLEAN;

BEGIN
  n := 100000000;

  { sieve of Eratosthenes: isComposite[i] = 1 iff i is not prime }
  NEW(isComposite, n);
  FOR i := 0 TO n DO
    isComposite^[i] := 0;
  isComposite^[0] := 1;
  isComposite^[1] := 1;
  i := 2;
  WHILE i * i <= n DO

reference_continuation:
  BEGIN
    IF isComposite^[i] = 0 THEN
    BEGIN
      j := i * i;
      WHILE j <= n DO
      BEGIN
        isComposite^[j] := 1;
        j := j + i
      END
    END;
    i := i + 1
  END;

  { m = pi(n); collect the primes up to n and the pi(.) prefix sum up to m }
  m := 0;
  FOR i := 2 TO n DO
    IF isComposite^[i] = 0 THEN
      m := m + 1;

  NEW(primes, m);
  idx := 0;
  FOR i := 2 TO n DO
    IF isComposite^[i] = 0 THEN
    BEGIN
      idx := idx + 1;
      primes^[idx] := i
    END;

  NEW(piOf, m);
  piOf^[0] := 0;
  FOR i := 1 TO m DO
    IF isComposite^[i] = 0 THEN
      piOf^[i] := piOf^[i - 1] + 1
    ELSE
      piOf^[i] := piOf^[i - 1];

  FOR k := 0 TO MAXK DO
    p[k] := 0;

  FOR v := 1 TO m DO
  BEGIN
    { u_0 in [primeVal, nextPrimeVal - 1] all have pi(u_0) = v; exactly
      primeVal itself is prime in that range }
    primeVal := primes^[v];
    IF v < m THEN
      nextPrimeVal := primes^[v + 1]
    ELSE
      nextPrimeVal := n + 1;
    intervalEnd := nextPrimeVal - 1;
    IF intervalEnd > n THEN
      intervalEnd := n;
    numNonPrime := intervalEnd - primeVal;

    cur := v;
    cval := 0;
    chainDone := FALSE;
    WHILE NOT chainDone DO
    BEGIN
      IF isComposite^[cur] = 1 THEN
        cval := cval + 1;
      p[cval] := p[cval] + 1;
      p[cval + 1] := p[cval + 1] + numNonPrime;
      IF cur = 1 THEN
        chainDone := TRUE
      ELSE
        cur := piOf^[cur]
    END
  END;

  modulus := 1000000007;
  answer := 1;
  FOR k := 0 TO MAXK DO
    IF p[k] > 0 THEN
      answer := (answer * (p[k] MOD modulus)) MOD modulus;
  WRITELN(answer);

  DISPOSE(isComposite);
  DISPOSE(primes);
  DISPOSE(piOf)
END.
